begin;
lock table public.site_meta in exclusive mode;
do $$ begin if (select version from public.site_meta where id=1) <> 0 then raise exception 'Carga inicial já executada; operação cancelada para preservar dados.'; end if; end $$;
update public.site_meta set version=1 where id=1;
commit;